import { cn } from "@/lib/utils";

interface Children {
  children: ReactNode;
}

interface AccordionProps extends Children {
  multiple?: boolean;
}
interface AccordionItemProps extends Children {
  value: string;
  className?: string;
  disabled?: boolean;
}
interface AccordionSummary extends Children {
  expandIcon?: ReactNode;
  isExpanded?: boolean;
  handleClick?: () => void;
  setHeights?: (prev: {}) => void;
  className?: string;
}
interface AccordionDetails extends Children {
  setHeights?: (prev: {}) => void;
  className?: string;
}
interface AccordionContextType {
  activeItem: string;
  setToggle: (value: string) => void;
  multiple: boolean;
}

const AccordionContext = createContext<AccordionContextType | undefined>(undefined);

const useAccordionContext = (): AccordionContextType => {
  const context = useContext(AccordionContext);
  if (!context) {
    throw new Error("No context found for Accordion");
  }
  return context;
};

const Accordion: FC<AccordionProps> = ({ children, multiple = true }) => {
  const [activeItem, setActiveItem] = useState("");

  const setToggle = (value: string) => {
    setActiveItem(() => (activeItem !== value ? value : ""));
  };

  return (
    <AccordionContext.Provider value={{ activeItem, setToggle, multiple }}>
      <div className="w-full">{children}</div>
    </AccordionContext.Provider>
  );
};

const AccordionSummary: FC<AccordionSummary> = ({
  children,
  isExpanded,
  handleClick,
  setHeights,
  expandIcon,
  className,
}) => {
  const ref = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (ref.current !== null) {
      setHeights?.((prev: {}) => ({ ...prev, summary: ref.current?.clientHeight }));
    }
  }, [setHeights]);

  return (
    <button
      ref={ref}
      className={cn("flex w-full cursor-pointer items-center justify-between p-4 font-medium", className)}
      onClick={handleClick}
    >
      <span className="text-start">{children}</span>
      <span className={`transition ${isExpanded && "rotate-180"}`}>
        {!expandIcon ? (
          <svg
            fill="none"
            width="24"
            height="24"
            shapeRendering="geometricPrecision"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
            viewBox="0 0 24 24"
          >
            <path d="M6 9l6 6 6-6"></path>
          </svg>
        ) : (
          expandIcon
        )}
      </span>
    </button>
  );
